const projects=[
 {title:'清洁科技 · 水下与家居',category:'clean',tags:'STARRYBOT / 泳池清洁器 · 布衣清洗机',intro:'小型泳池清洁器与冷水款布衣清洗机。通过主图、功能细节与使用场景，呈现清洁产品的特点。'},
 {title:'清洁科技 · 蒸汽与风力',category:'clean',tags:'STARRYBOT / 蒸汽清洗机 · 吹吸机',intro:'蒸汽款布衣清洗机与吹吸机。围绕产品结构、配件与使用场景展开的电商视觉系列。'},
 {title:'生活方式 · 便携与舒适',category:'life',tags:'LIFECREEK / 户外饭盒 · 空气净化器',intro:'便携户外饭盒与空气净化器。将产品融入生活场景，以细节画面传达功能与使用体验。'},
 {title:'清凉生活 · 冷风机',category:'life',tags:'LIFECREEK / 产品主图 · 功能视觉',intro:'冷风机系列电商视觉。展示产品外观、操作方式、气流和使用场景。'},
 {title:'让品牌，在现场被看见',category:'brand',tags:'展会视觉 / 广交会 · 展会海报',intro:'广交会及展会视觉物料。以产品组合、品牌识别与活动信息构建完整的展会海报表达。'},
 {title:'更多表达 · 品牌与包装',category:'brand',tags:'品牌平面 / 标志 · 包装 · 产品视觉',intro:'品牌标志、包装及其他产品视觉作品，探索不同品类的视觉语言。'}
];
const grid=document.querySelector('#projectGrid');
projects.forEach((p,i)=>{const card=document.createElement('article');card.className='project';card.dataset.category=p.category;card.innerHTML=`<button class="project-button" aria-label="查看${p.title}完整作品"><div class="project-image"><img src="assets/cover-${i+1}.webp" alt="${p.title}作品预览" loading="lazy" width="1400" height="900"><span class="view">查看项目 ↗</span></div><div class="project-meta"><div><h3>${p.title}</h3><p>${p.tags}</p></div><span class="project-number">0${i+1}</span></div></button>`;card.querySelector('button').addEventListener('click',()=>openProject(i));grid.append(card);});
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});document.querySelectorAll('.project').forEach(card=>card.hidden=button.dataset.filter!=='all'&&card.dataset.category!==button.dataset.filter);}));
const dialog=document.querySelector('#projectDialog');let currentProject=0;let projectFiles;let opener;
async function openProject(i){currentProject=i;const p=projects[i];document.querySelector('#dialogTitle').textContent=p.title;document.querySelector('#dialogNumber').textContent=`0${i+1} / 06`;document.querySelector('#dialogIntro').textContent=p.intro;document.querySelector('#dialogImages').replaceChildren();if(!dialog.open){opener=document.activeElement;dialog.showModal();document.body.style.overflow='hidden';}dialog.scrollTop=0;try{projectFiles=projectFiles||await fetch('assets/projects.json').then(r=>{if(!r.ok)throw Error();return r.json();});if(i!==currentProject||!dialog.open)return;projectFiles[i].forEach((file,n)=>{const image=new Image();image.alt=`${p.title} · 作品详情 ${n+1}`;image.src=`assets/${file}`;image.loading=n<2?'eager':'lazy';document.querySelector('#dialogImages').append(image);});}catch{document.querySelector('#dialogImages').textContent='图片暂时未能加载，请稍后再试。';}}
document.querySelector('#closeDialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});dialog.addEventListener('close',()=>{document.body.style.overflow='';opener?.focus({preventScroll:true});});document.querySelector('#nextProject').addEventListener('click',()=>openProject((currentProject+1)%projects.length));
document.querySelector('#copyPhone').addEventListener('click',async()=>{let message;try{await navigator.clipboard.writeText('18067560142');message='联系电话已复制';}catch{message='联系电话：18067560142';}const toast=document.querySelector('#toast');toast.textContent=message;toast.classList.add('visible');setTimeout(()=>toast.classList.remove('visible'),2600);});
